320.     pub fn map_kpage(
321.         &mut self,
322.         kpage: KernelPage,
323.         vaddr: PageAligned<VirtualAddress>,
324.     ) -> Result<(), Error> {
325.         let pt_vaddr: PageTableAddress = PageTableAddress::new(PageTableAligned::from_raw_value(
326.             ::sys::mm::align_down(vaddr.into_raw_value(), PGTAB_ALIGNMENT),
327.         )?);
328. 
329.         // Get the corresponding page directory entry.
330.         let pde: PageDirectoryEntry = match self.pgdir.read_pde(pt_vaddr) {
331.             Some(pde) => pde,
332.             None => {
333.                 let reason: &str = "failed to read page directory entry";
334.                 error!("{reason}");
335.                 return Err(Error::new(ErrorCode::TryAgain, reason));
336.             },
337.         };
338. 
339.         // Check if page table does not exist.
340.         if !pde.is_present() {
341.             let page_table: PageTable<PageTableStorage> = Self::allocate_kernel_page_table()?;
342. 
343.             // FIXME: do not be so open about permissions.
344.             self.pgdir.map(
345.                 pt_vaddr,
346.                 page_table.physical_address()?,
347.                 false,
348.                 AccessPermission::RDWR,
349.             )?;
350. 
351.             //===================================================================
352.             // NOTE: if we fail beyond this point we should unmap the page table.
353.             //===================================================================
354. 
355.             // Add page table to the list of kernel page tables.
356.             self.kernel_page_tables
357.                 .push_back(Rc::new(RefCell::new((pt_vaddr, page_table))));
358.         };
359. 
360.         // Get corresponding page table.
361.         let mut kernel_page_table_iter = self.kernel_page_tables.iter_mut();
362.         loop {
363.             let entry = match kernel_page_table_iter.next() {
364.                 Some(entry) => entry,
365.                 None => break,
366.             };
367.             if entry.borrow().0.into_raw_value() == pt_vaddr.into_raw_value() {
368.                 // Map the page to the target virtual address space.
369.                 // FIXME: do not be so open about permissions and caching.
370.                 entry.borrow_mut().1.map(
371.                     PageAddress::new(vaddr),
372.                     kpage.frame_address(),
373.                     true,
374.                     true,
375.                     false,
376.                     AccessPermission::RDWR,
377.                 )?;
378. 
379.                 // Add the kernel page to the list of kernel pages.
380.                 self.kernel_pages.push_back(Rc::new(RefCell::new(kpage)));
381. 
382.                 // Reload page directory to force a TLB flush.
383.                 self.load()?;
384. 
385.                 return Ok(());
386.             }
387.         }
388. 
389.         let reason: &str = "page table not found";
390.         error!("{reason}");
391.         Err(Error::new(ErrorCode::NoSuchEntry, reason))
392.     }
393. 
394.     ///
395.     /// # Description
396.     ///
397.     /// Allocate a page table for mapping kernel memory.
398.     ///
399.     /// # Returns
400.     ///
401.     /// Upon success, `Ok(page_table)` is returned. Upon failure, an error is returned.
402.     ///
403.     // Bare `external_body`, deferred to the proving phase: the returned value is the
404.     // concrete page-table representation that the View abstracts away (`internal_inv()`),
405.     // so it has no abstract postcondition until that representation is modeled.
406.     fn allocate_kernel_page_table() -> Result<PageTable<PageTableStorage>, Error> {
407.         let kpage: KernelPage = {
408.             // SAFETY: the memory manager is initialized and access is synchronized.
409.             let mm: &mut VirtMemoryManager = unsafe { VirtMemoryManager::get_mut() };
410.             mm.alloc_kpage(true)?
411.         };
412.         let pgtable_storage: PageTableStorage = PageTableStorage::KernelPage(kpage);
413.         let page_table: PageTable<PageTableStorage> = PageTable::new(pgtable_storage);
414.         Ok(page_table)
415.     }
416. 
417.     ///
418.     /// # Description
419.     ///
420.     /// Allocate a page table for mapping user memory.
421.     ///
422.     /// # Returns
423.     ///
424.     /// Upon success, `Ok(page_table)` is returned. Upon failure, an error is returned.
425.     ///
426.     // Bare `external_body`, deferred to the proving phase: the returned value is the
427.     // concrete page-table representation that the View abstracts away (`internal_inv()`),
428.     // so it has no abstract postcondition until that representation is modeled.
429.     fn allocate_user_page_table() -> Result<PageTable<PageTableStorage>, Error> {
430.         // SAFETY: the kernel is single-threaded and runs with interrupts disabled; no
431.         // concurrent or re-entrant access to the physical memory manager is possible.
432.         let mut kframe: KernelFrame =
433.             unsafe { PhysMemoryManager::get_mut() }.alloc_kernel_frame()?;
434.         kframe.clear()?;
435.         let kpage: KernelPage = KernelPage::new(kframe);
436.         let pgtable_storage: PageTableStorage = PageTableStorage::KernelPage(kpage);
